def process_order(order_id: int, user_id: int, amount: float) -> dict:
    """Process an order for a user."""
    if amount <= 0:
        return {"error": "Amount must be positive"}

    # Fetch user
    user = get_user(user_id)
    if not user:
        return {"error": "User not found"}

    # Check balance
    if user.balance < amount:
        return {"error": "Insufficient balance"}

    # Deduct balance
    user.balance -= amount

    # Create order record
    order = create_order(order_id, user_id, amount)

    # Send confirmation
    send_email(user.email, f"Order {order_id} confirmed for ${amount}")

    return {"success": True, "order": order}


